    try { if (typeof risuAPI !== 'undefined') push(risuAPI); } catch (_) {}
    try { if (typeof Risuai !== 'undefined') push(Risuai); } catch (_) {}
    try { if (typeof RisuAI !== 'undefined') push(RisuAI); } catch (_) {}
