    const set = (stage, value) => {
      priorities[stage] ||= {};
      priorities[stage][skillId] = value;
    };
    if (scope === 'inactive') SKILL_STAGE_IDS.forEach(stage => set(stage, 0));
    else if (SKILL_STAGE_IDS.includes(scope)) SKILL_STAGE_IDS.forEach(stage => set(stage, stage === scope ? 100 : 0));
    else if (scope === 'all_high') SKILL_STAGE_IDS.forEach(stage => set(stage, 80));
    else {
      // auto: leave user overrides empty and use the custom default 45 in all stages.
      for (const stage of SKILL_STAGE_IDS) {
        if (!priorities[stage]) continue;
        delete priorities[stage][skillId];
        if (!Object.keys(priorities[stage]).length) delete priorities[stage];
      }
    }
    runtime.skillPriorityOverrides = priorities;
